import{_ as s,c as a,d as t,o as e}from"./app-DVOSHj31.js";const p={};function o(c,n){return e(),a("div",null,[...n[0]||(n[0]=[t(`<h1 id="go-wind-uba-拆解系列-sdk-与采集层-从浏览器到-kafka" tabindex="-1"><a class="header-anchor" href="#go-wind-uba-拆解系列-sdk-与采集层-从浏览器到-kafka"><span>Go Wind UBA 拆解系列 - SDK 与采集层：从浏览器到 Kafka</span></a></h1><blockquote><p>本文回答一个问题：<strong>一个埋点事件，从用户在浏览器里点了一下，到最终被 Kafka 接住，中间的 SDK 和 Collector 做了多少你看不见的工程？</strong> 答案是：比你想象的多得多。</p></blockquote><h2 id="一、为什么-采集-这件事很难" tabindex="-1"><a class="header-anchor" href="#一、为什么-采集-这件事很难"><span>一、为什么&quot;采集&quot;这件事很难</span></a></h2><p>很多人以为埋点 SDK 就是 <code>fetch(&#39;/report&#39;, { body: event })</code>。这在 demo 里成立，在生产里不成立。真实的采集层要回答这些问题：</p><ul><li><strong>页面随时可能关闭</strong>——用户点完就关 tab，残留事件怎么办？</li><li><strong>网络随时可能抖动</strong>——一次失败就丢数据？还是重试？重试几次？退避多久？</li><li><strong>服务端可能限流</strong>——429 要重试，但 401（鉴权失败）不该重试，怎么区分？</li><li><strong>批量还是单条</strong>——单条上报开销大，批量要攒多久、攒多少？</li><li><strong>客户端环境千差万别</strong>——浏览器的 sendBeacon、Unity WebGL 不能用 HttpClient、小程序没有 localStorage……</li><li><strong>凭证放哪</strong>——放 Header 还是 body？前者标准但不支持 sendBeacon。</li></ul><p>GoWind UBA 的两个 SDK（Web TS / C# .NET）和 Collector 服务，把这些都处理了。本文逐个拆。</p><h2 id="二、web-sdk-一个克制的批量上报器" tabindex="-1"><a class="header-anchor" href="#二、web-sdk-一个克制的批量上报器"><span>二、Web SDK：一个克制的批量上报器</span></a></h2><p>Web SDK 在 <code>frontend/sdk/web/uba/src/</code>，6 个模块。架构很干净：<code>UbaClient</code>（高层 API + 事件构造）委托给 <code>Batcher</code>（缓冲 + 触发），<code>Batcher</code> 委托给 <code>retry.ts</code>（网络 + 重试）。上下文（设备/会话/平台）独立在 <code>context.ts</code>。</p><h3 id="_2-1-ubaclient-单例-事件构造" tabindex="-1"><a class="header-anchor" href="#_2-1-ubaclient-单例-事件构造"><span>2.1 UbaClient：单例 + 事件构造</span></a></h3><p><code>UbaClient</code> 是个<strong>单例</strong>，挂在 <code>globalThis.__uba_client__</code> 上。<code>init()</code> 会先 tear down 旧实例再重建，避免重复初始化。</p><p>所有事件都走一个唯一的构造漏斗 <code>buildEvent</code>——这是关键设计，保证每条事件的结构一致：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">const</span> eventTime <span class="token operator">=</span> <span class="token function">toRFC3339</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> mergedProps <span class="token operator">=</span> <span class="token function">merge</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>superProperties<span class="token punctuation">,</span> properties<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 公共属性 + 本次属性</span></span>
<span class="line"><span class="token keyword">const</span> pageUrl <span class="token operator">=</span> <span class="token function">getPageUrl</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>pageUrl <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>mergedProps<span class="token punctuation">.</span>pageUrl<span class="token punctuation">)</span> mergedProps<span class="token punctuation">.</span>pageUrl <span class="token operator">=</span> pageUrl<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">return</span> <span class="token punctuation">{</span></span>
<span class="line">  eventType<span class="token punctuation">,</span> eventId<span class="token operator">:</span> <span class="token function">uuid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> eventName<span class="token punctuation">,</span> eventTime<span class="token punctuation">,</span></span>
<span class="line">  userId<span class="token operator">:</span> options<span class="token operator">?.</span>userId <span class="token operator">??</span> <span class="token keyword">this</span><span class="token punctuation">.</span>userId<span class="token punctuation">,</span></span>
<span class="line">  deviceId<span class="token operator">:</span> options<span class="token operator">?.</span>deviceId <span class="token operator">??</span> <span class="token function">getDeviceId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  sessionId<span class="token operator">:</span> options<span class="token operator">?.</span>sessionId <span class="token operator">??</span> <span class="token function">getSessionId</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">  platform<span class="token operator">:</span> options<span class="token operator">?.</span>platform <span class="token operator">??</span> <span class="token keyword">this</span><span class="token punctuation">.</span>platform<span class="token punctuation">,</span></span>
<span class="line">  properties<span class="token operator">:</span> Object<span class="token punctuation">.</span><span class="token function">keys</span><span class="token punctuation">(</span>mergedProps<span class="token punctuation">)</span><span class="token punctuation">.</span>length <span class="token operator">&gt;</span> <span class="token number">0</span> <span class="token operator">?</span> mergedProps <span class="token operator">:</span> <span class="token keyword">undefined</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>setSuperProperties({ platform: &#39;web&#39;, version: &#39;1.0.0&#39; })</code> 设的公共属性，会<strong>自动合并进后续每一条事件</strong>。<code>trackBehavior</code> / <code>trackRisk</code> 都是调 <code>buildEvent</code> 后再挂一个 <strong>oneof 载荷</strong>（<code>event.behavior</code> / <code>event.risk</code>）——这跟后端 proto 的 oneof 契约对齐。</p><h3 id="_2-2-batcher-双触发-并发守卫" tabindex="-1"><a class="header-anchor" href="#_2-2-batcher-双触发-并发守卫"><span>2.2 Batcher：双触发 + 并发守卫</span></a></h3><p>这是 SDK 的心脏。<code>Batcher</code> 持一个内存队列 <code>queue</code>、一个 <code>setInterval</code> 定时器、一个 <code>flushing</code> 布尔守卫。两个触发条件：</p><p><strong>触发 1：攒够了</strong>（<code>batcher.ts</code>）</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token function">enqueue</span><span class="token punctuation">(</span>event<span class="token operator">:</span> ReportEvent<span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>event<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span>length <span class="token operator">&gt;=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>opts<span class="token punctuation">.</span>batchSize<span class="token punctuation">)</span> <span class="token punctuation">{</span>   <span class="token comment">// 默认 batchSize=20</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">flush</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>触发 2：定时到了</strong>——<code>setInterval</code> 每 <code>flushInterval</code>（默认 5000ms）调一次 <code>flush()</code>。在 Node 环境下调 <code>.unref()</code>，避免 timer 卡住进程退出。</p><p><code>flush()</code> 的核心是<strong>并发守卫</strong>：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">this</span><span class="token punctuation">.</span>flushing <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">const</span> events <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span><span class="token function">splice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 原子清空</span></span>
<span class="line"><span class="token keyword">try</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> body <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">buildBody</span><span class="token punctuation">(</span>events<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">sendWithRetry</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>opts<span class="token punctuation">.</span>url<span class="token punctuation">,</span> body<span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token operator">...</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span> <span class="token keyword">finally</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">this</span><span class="token punctuation">.</span>flushing <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>同一时间只有一个 in-flight 的 send。</strong> 并发的 <code>flush()</code> 调用会短路返回。这个设计保证了：不会因为重试风暴把服务端打爆。</p><p><strong>凭证在 body，不在 Header</strong>（<code>buildBody</code>）：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token comment">// body = { appId, appSecret, events, clientInfo }</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这是<strong>整条链路的契约起点</strong>。后面会看到，正是这个选择让 sendBeacon 兜底成为可能。</p><h3 id="_2-3-重试与降级-精确区分状态码" tabindex="-1"><a class="header-anchor" href="#_2-3-重试与降级-精确区分状态码"><span>2.3 重试与降级：精确区分状态码</span></a></h3><p><code>sendWithRetry</code> 的重试策略值得细看（<code>retry.ts</code>）：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">function</span> <span class="token function">isNoRetryStatus</span><span class="token punctuation">(</span>status<span class="token operator">:</span> <span class="token builtin">number</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token builtin">boolean</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">return</span> status <span class="token operator">&gt;=</span> <span class="token number">400</span> <span class="token operator">&amp;&amp;</span> status <span class="token operator">&lt;</span> <span class="token number">500</span> <span class="token operator">&amp;&amp;</span> status <span class="token operator">!==</span> <span class="token number">429</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 循环 maxRetries+1 次</span></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> attempt <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> attempt <span class="token operator">&lt;=</span> cfg<span class="token punctuation">.</span>maxRetries<span class="token punctuation">;</span> attempt<span class="token operator">++</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  result <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">sendOnce</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> body<span class="token punctuation">,</span> cfg<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>result<span class="token punctuation">.</span>ok<span class="token punctuation">)</span> <span class="token keyword">return</span> result<span class="token punctuation">;</span>                        <span class="token comment">// 2xx：成功</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">isNoRetryStatus</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>status<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> result<span class="token punctuation">;</span>   <span class="token comment">// 4xx（除 429）：不重试</span></span>
<span class="line">  <span class="token comment">// 否则退避重试</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span>attempt <span class="token operator">&lt;</span> cfg<span class="token punctuation">.</span>maxRetries<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">const</span> delay <span class="token operator">=</span> cfg<span class="token punctuation">.</span>baseDelay <span class="token operator">*</span> Math<span class="token punctuation">.</span><span class="token function">pow</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> attempt<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 指数退避</span></span>
<span class="line">    <span class="token keyword">await</span> <span class="token function">sleep</span><span class="token punctuation">(</span>delay<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三个关键决策：</p><ol><li><strong>401/400 不重试</strong>——鉴权失败或参数错误，重试也是错，浪费请求。直接放弃。</li><li><strong>429 要重试</strong>——服务端限流，过会儿可能就好了。</li><li><strong>5xx / 网络错误重试</strong>——指数退避（<code>baseDelay * 2^attempt</code>，默认 baseDelay=1000ms）。</li></ol><p><strong>重试耗尽后怎么办？丢掉，不回填队列。</strong> 这是有意的——避免无限堆积导致内存爆炸。源码注释明说：宁可丢一批，也不能让 SDK 内存无限增长。</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>result<span class="token punctuation">.</span>success<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  dropped <span class="token operator">=</span> events<span class="token punctuation">.</span>length<span class="token punctuation">;</span>   <span class="token comment">// 直接计入 dropped</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>sendOnce</code> 用 <code>AbortController</code> 控超时（默认 8000ms），发 <code>credentials: &#39;omit&#39;</code>（不带 cookie，避免干扰 app-secret 鉴权）。</p><h3 id="_2-4-页面卸载兜底-sendbeacon" tabindex="-1"><a class="header-anchor" href="#_2-4-页面卸载兜底-sendbeacon"><span>2.4 页面卸载兜底：sendBeacon</span></a></h3><p>这是 Web SDK 最有 browser 特色的部分。浏览器关闭页面时，普通 fetch 会被取消；唯有 <code>navigator.sendBeacon</code> 能在卸载时可靠发出去（但它不能设 Header、不能等响应）。</p><p>SDK 注册了<strong>双事件</strong>兜底（移动端 + 桌面端覆盖）：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token keyword">private</span> <span class="token function">bindUnload</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">const</span> <span class="token function-variable function">handler</span> <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token keyword">this</span><span class="token punctuation">.</span>batcher<span class="token punctuation">.</span><span class="token function">flushBeacon</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;pagehide&#39;</span><span class="token punctuation">,</span> handler<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// 移动端友好</span></span>
<span class="line">  window<span class="token punctuation">.</span><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;beforeunload&#39;</span><span class="token punctuation">,</span> handler<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 桌面端</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>flushBeacon</code> 是<strong>尽力而为</strong>（<code>batcher.ts</code>）：</p><div class="language-typescript line-numbers-mode" data-highlighter="prismjs" data-ext="ts"><pre><code><span class="line"><span class="token function">flushBeacon</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">:</span> <span class="token keyword">void</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token keyword">this</span><span class="token punctuation">.</span>opts<span class="token punctuation">.</span>enableBeacon <span class="token operator">||</span> <span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span>length <span class="token operator">===</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> events <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span><span class="token function">splice</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span> <span class="token keyword">this</span><span class="token punctuation">.</span>queue<span class="token punctuation">.</span>length<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> body <span class="token operator">=</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">buildBody</span><span class="token punctuation">(</span>events<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token keyword">const</span> ok <span class="token operator">=</span> <span class="token function">sendBeacon</span><span class="token punctuation">(</span><span class="token keyword">this</span><span class="token punctuation">.</span>opts<span class="token punctuation">.</span>url<span class="token punctuation">,</span> body<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// 用 Blob 包装，异步发出</span></span>
<span class="line">  <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>ok<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">this</span><span class="token punctuation">.</span>opts<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;warn&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;sendBeacon failed, events lost on unload&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意几个取舍：</p><ul><li><strong>sendBeacon 发的就是 fetch 同样的 body</strong>（含 appId/appSecret）——正是因为凭证在 body，sendBeacon 才能用。<strong>如果把凭证放 Header，这一层兜底就彻底废了。</strong> 这就是为什么鉴权在 body 是深思熟虑的选择。</li><li><strong>失败就丢</strong>——sendBeacon 没法重试（页面都没了），SDK 只能 log warn。这是 browser 环境的硬限制，没有银弹。</li></ul><h3 id="_2-5-上下文-设备-会话-平台" tabindex="-1"><a class="header-anchor" href="#_2-5-上下文-设备-会话-平台"><span>2.5 上下文：设备 / 会话 / 平台</span></a></h3><p><code>context.ts</code> 负责生成稳定标识：</p><ul><li><strong>deviceId</strong>：存 <code>localStorage</code>（<code>__uba_device_id__</code>），跨会话稳定；无 localStorage 时（隐私模式 / Node）退回内存变量。</li><li><strong>sessionId</strong>：存 <code>sessionStorage</code>（<code>__uba_session_id__</code>），tab 级隔离（关 tab 清掉）；同样有内存兜底。</li><li><strong>platform</strong>：UA 嗅探，返回 <code>web/ios/android/mini_program/node</code>；小程序靠 <code>window.wx.getSystemInfo</code> 存在性识别。</li></ul><p>热力图用的<strong>点击坐标</strong>和 <strong>XPath</strong> 也在这里算：坐标加上 scroll offset 换算到文档坐标，XPath 用于元素定位。自动埋点的 click 监听绑在<strong>捕获阶段</strong>（<code>addEventListener(&#39;click&#39;, handler, true)</code>），保证在业务逻辑之前触发。</p><h3 id="_2-6-默认值一览" tabindex="-1"><a class="header-anchor" href="#_2-6-默认值一览"><span>2.6 默认值一览</span></a></h3><p>记一下默认值，跟 C# SDK 是镜像的（后文验证）：</p><table><thead><tr><th>参数</th><th>默认值</th></tr></thead><tbody><tr><td>batchSize</td><td>20</td></tr><tr><td>flushInterval</td><td>5000ms</td></tr><tr><td>maxRetries</td><td>3</td></tr><tr><td>timeout</td><td>8000ms</td></tr><tr><td>retryBaseDelay</td><td>1000ms</td></tr><tr><td>enableBeacon</td><td>true</td></tr><tr><td>autoTrack</td><td>true</td></tr></tbody></table><h2 id="三、c-sdk-零依赖核心-可注入传输" tabindex="-1"><a class="header-anchor" href="#三、c-sdk-零依赖核心-可注入传输"><span>三、C# SDK：零依赖核心 + 可注入传输</span></a></h2><p>C# SDK 在 <code>sdk/csharp/src/</code>，两个项目：<code>Uba.Core</code>（.NET Standard 2.0，覆盖 Unity / Godot）和 <code>Uba.Unity</code>（Unity 适配）。API 跟 TS 版几乎同构（<code>Track</code> / <code>TrackBehavior</code> / <code>TrackRisk</code> / <code>Identify</code> / <code>SetSuperProperties</code> / <code>FlushAsync</code>），默认值也完全一样——这是有意为之，方便团队跨端接入时心智一致。</p><p>但有一个<strong>架构性差异</strong>：C# 版的<strong>传输层和上下文都是可注入的</strong>。</p><h3 id="_3-1-ihttptransport-为-unity-webgl-留的口子" tabindex="-1"><a class="header-anchor" href="#_3-1-ihttptransport-为-unity-webgl-留的口子"><span>3.1 IHttpTransport：为 Unity WebGL 留的口子</span></a></h3><p>为什么要抽象传输层？因为 Unity WebGL 是个特殊环境。接口注释写得很清楚（<code>Transport.cs</code>）：</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code><span class="line"><span class="token doc-comment comment">/// HTTP 传输抽象。核心库提供 HttpClientTransport；Unity 侧可用 UnityWebRequestTransport 覆盖。</span></span>
<span class="line"><span class="token doc-comment comment">/// 抽象出此接口是为了让 Unity WebGL（HttpClient 不可用）能替换实现。</span></span>
<span class="line"><span class="token keyword">public</span> <span class="token keyword">interface</span> <span class="token class-name">IHttpTransport</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token return-type class-name">Task<span class="token punctuation">&lt;</span>FetchResult<span class="token punctuation">&gt;</span></span> <span class="token function">SendAsync</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> url<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> body<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">int</span></span> timeoutMs<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> ct <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Unity WebGL 里 HttpClient 会抛 <code>PlatformNotSupportedException</code>。</strong> 原因是 WebGL 没有原生 socket，浏览器只开放了 fetch 风格的 <code>UnityWebRequest</code> API。所以必须替换传输实现。</p><p><code>UbaClient</code> 构造函数接受可选的 transport 和 context：</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token function">UbaClient</span><span class="token punctuation">(</span><span class="token class-name">UbaConfig</span> config<span class="token punctuation">,</span> <span class="token class-name">IHttpTransport<span class="token punctuation">?</span></span> transport <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">,</span> <span class="token class-name">IContextProvider<span class="token punctuation">?</span></span> context <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">Validate</span><span class="token punctuation">(</span>config<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    _config <span class="token operator">=</span> config<span class="token punctuation">;</span></span>
<span class="line">    _config<span class="token punctuation">.</span>Endpoint <span class="token operator">=</span> <span class="token punctuation">(</span>_config<span class="token punctuation">.</span>Endpoint <span class="token operator">??</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">TrimEnd</span><span class="token punctuation">(</span><span class="token char">&#39;/&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    _context <span class="token operator">=</span> context <span class="token operator">??</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">DefaultContextProvider</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    _batcher <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Batcher</span><span class="token punctuation">(</span>_config<span class="token punctuation">,</span> transport <span class="token operator">??</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">HttpClientTransport</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                           <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> _context<span class="token punctuation">.</span><span class="token function">GetClientInfo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> Log<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>默认走 <code>HttpClientTransport</code>（.NET Core / Mono / Unity 原生平台都能用）；Unity WebGL 注入 <code>UnityWebRequestTransport</code>。<strong>这就是依赖注入解决真实问题的范例</strong>——不是为了解耦而解耦，是为了对付平台差异。</p><p><code>HttpClientTransport</code> 用<strong>静态共享 HttpClient</strong>（socket 复用），<code>CancellationTokenSource</code> 控超时，把&quot;无外部取消的 OperationCanceledException&quot;判为超时。它的 <code>ParseResult</code> 是 <code>public static</code>，专门让 Unity 适配器复用响应解析。</p><h3 id="_3-2-unitywebrequesttransport-把协程桥接到-task" tabindex="-1"><a class="header-anchor" href="#_3-2-unitywebrequesttransport-把协程桥接到-task"><span>3.2 UnityWebRequestTransport：把协程桥接到 Task</span></a></h3><p>Unity 的 <code>UnityWebRequest</code> 必须<strong>在主线程</strong>跑，而且是<strong>协程</strong>风格。怎么跟 <code>Task</code> 接口对接？用 <code>TaskCompletionSource</code>（<code>UnityWebRequestTransport.cs</code>）：</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code><span class="line"><span class="token keyword">public</span> <span class="token return-type class-name">Task<span class="token punctuation">&lt;</span>FetchResult<span class="token punctuation">&gt;</span></span> <span class="token function">SendAsync</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">string</span></span> url<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">string</span></span> body<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">int</span></span> timeoutMs<span class="token punctuation">,</span> <span class="token class-name">CancellationToken</span> ct <span class="token operator">=</span> <span class="token keyword">default</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name"><span class="token keyword">var</span></span> tcs <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">TaskCompletionSource<span class="token punctuation">&lt;</span>FetchResult<span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span>TaskCreationOptions<span class="token punctuation">.</span>RunContinuationsAsynchronously<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    _host<span class="token punctuation">.</span><span class="token function">StartCoroutine</span><span class="token punctuation">(</span><span class="token function">SendCoroutine</span><span class="token punctuation">(</span>url<span class="token punctuation">,</span> body<span class="token punctuation">,</span> timeoutMs<span class="token punctuation">,</span> tcs<span class="token punctuation">,</span> ct<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 在 MonoBehaviour host 上启协程</span></span>
<span class="line">    <span class="token keyword">return</span> tcs<span class="token punctuation">.</span>Task<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>协程里每帧轮询 <code>op.isDone</code>，超时手动 abort，完成后 resolve TCS。还用 <code>#if UNITY_2020_2_OR_NEWER</code> 区分 Unity 版本的错误 API（<code>req.result</code> vs <code>req.isHttpError/isNetworkError</code>）。响应解码复用 <code>HttpClientTransport.ParseResult</code>，不重复造轮子。</p><h3 id="_3-3-batcher-线程安全版" tabindex="-1"><a class="header-anchor" href="#_3-3-batcher-线程安全版"><span>3.3 Batcher：线程安全版</span></a></h3><p>C# 是多线程环境（不像 JS 单线程），所以 Batcher 用了 <code>lock</code> + <code>Interlocked</code> 做并发控制（<code>Batcher.cs</code>）：</p><div class="language-csharp line-numbers-mode" data-highlighter="prismjs" data-ext="cs"><pre><code><span class="line"><span class="token keyword">if</span> <span class="token punctuation">(</span>Interlocked<span class="token punctuation">.</span><span class="token function">CompareExchange</span><span class="token punctuation">(</span><span class="token keyword">ref</span> _flushing<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">0</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">FlushResult</span> <span class="token punctuation">{</span> Success <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span>        <span class="token comment">// 已有 flush 在跑，短路</span></span>
<span class="line"><span class="token class-name">List<span class="token punctuation">&lt;</span>ReportEvent<span class="token punctuation">&gt;</span></span> events<span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">lock</span> <span class="token punctuation">(</span>_lock<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">if</span> <span class="token punctuation">(</span>_queue<span class="token punctuation">.</span>Count <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> _flushing <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span> <span class="token keyword">return</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">FlushResult</span> <span class="token punctuation">{</span> Success <span class="token operator">=</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">;</span> <span class="token punctuation">}</span></span>
<span class="line">    events <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">List<span class="token punctuation">&lt;</span>ReportEvent<span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span>_queue<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    _queue<span class="token punctuation">.</span><span class="token function">Clear</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>重试逻辑跟 TS 完全一致（指数退避、4xx 除 429 不重试、耗尽即丢），只是内联在 batcher 里（TS 是独立模块）。<strong>C# 版没有 sendBeacon 等价物</strong>——因为 Unity / Godot 这些运行时不存在&quot;tab 关闭丢数据&quot;问题，这是 TS 独有的 browser 痛点。</p><h3 id="_3-4-零依赖-手写-json-序列化器" tabindex="-1"><a class="header-anchor" href="#_3-4-零依赖-手写-json-序列化器"><span>3.4 零依赖：手写 JSON 序列化器</span></a></h3><p>这是 C# SDK 最&quot;较真&quot;的地方。<code>Uba.Core.csproj</code> <strong>零 PackageReference</strong>——确认过，没有任何 NuGet 包。目标 <code>netstandard2.0</code>。</p><p>代价是<strong>手写了一个 JSON 序列化器</strong>（<code>Json.cs</code>）。它的注释说得很直白：</p><blockquote><p>仅服务于本库的请求序列化...不实现通用 JSON，保持极简、可审计。</p></blockquote><p>它发 camelCase key、跳过 null、手写一个 <code>JsonRead</code> 用 <code>&quot;key&quot;</code> 子串扫描找标量值，<strong>不构建完整 DOM</strong>。这一切只为了<strong>不引入 <code>System.Text.Json</code> 或 <code>Newtonsoft.Json</code></strong>——让 DLL 干净到能直接丢进 Unity 的 <code>Assets/Plugins/</code>。</p><p>为什么这么执着于零依赖？因为 Unity 项目对依赖极度敏感：引入一个 JSON 库可能跟 Unity 自带的冲突，或者 IL2CPP 编译时出问题。零依赖 = 部署零摩擦。<strong>这是一个为游戏开发者量身定制的取舍</strong>，也是&quot;游戏专项&quot;不只是后端分析模型、连 SDK 都照顾到的体现。</p><h2 id="四、collector-把采集数据接住" tabindex="-1"><a class="header-anchor" href="#四、collector-把采集数据接住"><span>四、Collector：把采集数据接住</span></a></h2><p>Collector 在 第 1 篇 已概览过，这里聚焦采集链路特有的细节。</p><h3 id="_4-1-鉴权-加固实现" tabindex="-1"><a class="header-anchor" href="#_4-1-鉴权-加固实现"><span>4.1 鉴权：加固实现</span></a></h3><p><code>AppAuthenticator</code>（<code>app_auth.go</code>）有几个安全细节，每一个都解决一类真实攻击：</p><p><strong>① Redis 只存哈希，不存明文密钥：</strong></p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">type</span> cachedApp <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    AppID      <span class="token builtin">string</span> <span class="token string">\`json:&quot;app_id&quot;\`</span></span>
<span class="line">    SecretHash <span class="token builtin">string</span> <span class="token string">\`json:&quot;secret_hash&quot;\`</span>  <span class="token comment">// sha256(app_secret) 的十六进制串</span></span>
<span class="line">    Status     ubaV1<span class="token punctuation">.</span>Application_Status</span>
<span class="line">    TenantID   <span class="token builtin">uint32</span> <span class="token string">\`json:&quot;tenant_id&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Redis 被脱库 ≠ 密钥泄露。</p><p><strong>② constant-time 比较，防时序攻击：</strong></p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">inHash <span class="token operator">:=</span> <span class="token function">sha256Hex</span><span class="token punctuation">(</span>appSecret<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> subtle<span class="token punctuation">.</span><span class="token function">ConstantTimeCompare</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span>inHash<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span>app<span class="token punctuation">.</span>SecretHash<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token number">1</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> collectorV1<span class="token punctuation">.</span><span class="token function">ErrorIncorrectAppSecret</span><span class="token punctuation">(</span><span class="token operator">...</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>普通字符串比较会在第一个不匹配字节提前返回，攻击者可据此逐字节爆破。<code>subtle.ConstantTimeCompare</code> 消耗固定时间。</p><p><strong>③ 负缓存防穿透：</strong> 不存在的 appId 也写进 Redis（TTL 1 分钟）。攻击者拿假 appId 暴力试探，第一次会打穿到 DB，但之后 1 分钟内都被 Redis 挡住。正常 appId 缓存 10 分钟。</p><p><strong>④ 可用性 ≠ 鉴权失败：</strong> gRPC 查应用失败时返回 <code>InternalServerError</code>，不返回 <code>Unauthorized</code>。一次网络抖动不该让客户端误以为密钥错了，触发改密钥的误操作。</p><p><strong>⑤ 状态检查：</strong> 只有 <code>Application_ON</code> 的应用能通过，禁用的应用哪怕密钥对也拒。</p><h3 id="_4-2-字段回填的微妙之处" tabindex="-1"><a class="header-anchor" href="#_4-2-字段回填的微妙之处"><span>4.2 字段回填的微妙之处</span></a></h3><p><code>handleBehavior</code> 有个值得讲的设计：业务扩展字段的回填策略。它<strong>优先取 behavior oneof 里的值</strong>，只有对&quot;有存在性语义&quot;的字段（空串 / nil / len==0 才算未设）才回退到顶层 <code>ReportEvent</code>。</p><p>但<strong>数值标量不回退</strong>（<code>SessionSeq</code> / <code>DurationMs</code> / <code>Quantity</code> / <code>Score</code>）。源码注释解释：proto3 区分不了&quot;未设&quot;和&quot;显式 0&quot;——如果回退，会把合法的 <code>Score=0</code>（用户真打了 0 分）错改成顶层默认值。这是 proto3 的经典坑，作者识别到了并主动回避。</p><h3 id="_4-3-两个-topic" tabindex="-1"><a class="header-anchor" href="#_4-3-两个-topic"><span>4.3 两个 Topic</span></a></h3><p>Collector 发布到两个 Kafka topic（<code>backend/pkg/topic/kafka.go</code>）：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">UbaEventRaw  <span class="token operator">=</span> <span class="token string">&quot;uba_events_raw&quot;</span>    <span class="token comment">// 原始行为事件</span></span>
<span class="line">UbaEventRisk <span class="token operator">=</span> <span class="token string">&quot;uba_risk_events&quot;</span>   <span class="token comment">// 风险事件</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>行为事件和风险事件分 topic，便于下游独立消费 / 独立扩容。文件里还定义了 <code>uba_events_enriched</code> / <code>uba_path_events</code> / sync / alert / audit / DLQ topic 和消费组名——这些属于下游消费者，不在 collector 的发布路径。</p><blockquote><p>如 第 1 篇 所述，<strong>Core 内消费这两个 topic 入库的 subscriber 尚未实现</strong>。Collector 这端是通的，Core 也具备 <code>BatchCreate</code> 入库能力，连接它们的管线是生产化前要补的一环。</p></blockquote><h2 id="五、跨端契约的一致性" tabindex="-1"><a class="header-anchor" href="#五、跨端契约的一致性"><span>五、跨端契约的一致性</span></a></h2><p>把三个端（TS SDK / C# SDK / Collector）放在一起看，会发现契约是<strong>有意保持对称</strong>的：</p><table><thead><tr><th>维度</th><th>TS SDK</th><th>C# SDK</th><th>Collector</th></tr></thead><tbody><tr><td>batchSize</td><td>20</td><td>20</td><td>—</td></tr><tr><td>flushInterval</td><td>5000ms</td><td>5000ms</td><td>—</td></tr><tr><td>maxRetries</td><td>3</td><td>3</td><td>—</td></tr><tr><td>timeout</td><td>8000ms</td><td>8000ms</td><td>服务端 10s</td></tr><tr><td>退避</td><td><code>base * 2^n</code></td><td><code>base * 2^n</code></td><td>—</td></tr><tr><td>4xx 处理</td><td>除 429 不重试</td><td>除 429 不重试</td><td>—</td></tr><tr><td>凭证位置</td><td>body</td><td>body</td><td>从 body 读</td></tr><tr><td>卸载兜底</td><td>sendBeacon</td><td>无（不需要）</td><td>—</td></tr></tbody></table><p>两个细节值得强调：</p><ol><li><strong>客户端 timeout 8s &lt; 服务端 10s</strong>——避免客户端先超时放弃、服务端还在处理造成&quot;幽灵请求&quot;。两个 SDK 的 Config 文档都标注了这点。</li><li><strong>凭证在 body</strong> 是三端共同契约。这是 sendBeacon 能 work 的前提（前面讲过），也让 CORS 简单（不需要预检自定义 Header）。</li></ol><h2 id="六、小结-采集层的工程美学" tabindex="-1"><a class="header-anchor" href="#六、小结-采集层的工程美学"><span>六、小结：采集层的工程美学</span></a></h2><p>回到开头的问题——采集层做了多少看不见的工程？答案是：</p><ul><li><strong>可靠性</strong>：批量、指数退避重试、状态码精确区分、并发守卫。</li><li><strong>环境适配</strong>：Web 的 sendBeacon 兜底、Unity WebGL 的传输注入、隐私模式的内存兜底。</li><li><strong>安全</strong>：哈希存储、constant-time 比较、负缓存、tenantId 权威覆盖。</li><li><strong>契约对称</strong>：TS / C# / 服务端三端默认值和策略镜像，降低跨端心智成本。</li><li><strong>克制</strong>：C# 手写 JSON 序列化器追求零依赖，SDK 重试耗宁丢不堆。</li></ul><p>这些每一项都不复杂，但<strong>组合起来才是一个生产级采集层</strong>。很多人低估了埋点 SDK 的难度——它不难在算法，难在&quot;在不可靠的客户端环境里可靠地、克制地把数据送出去&quot;。GoWind UBA 在这件事上做得相当扎实。</p><hr><p><em>本文代码出自 <a href="https://github.com/tx7do/go-wind-uba" target="_blank" rel="noopener noreferrer">go-wind-uba</a>： Web SDK <code>frontend/sdk/web/uba/src/</code>、C# SDK <code>sdk/csharp/src/</code>、Collector <code>backend/app/collector/service/internal/service/</code>。</em></p>`,104)])])}const i=s(p,[["render",o]]),r=JSON.parse(`{"path":"/posts/go-wind-uba-sdk-and-collector.html","title":"Go Wind UBA 拆解系列 - SDK 与采集层：从浏览器到 Kafka","lang":"zh-CN","frontmatter":{"date":"2026-07-02T00:00:00.000Z","category":["GoWind风行"],"tag":["UBA","大数据分析","Golang","GoWind"],"sticky":10},"headers":[{"level":2,"title":"一、为什么\\"采集\\"这件事很难","slug":"一、为什么-采集-这件事很难","link":"#一、为什么-采集-这件事很难","children":[]},{"level":2,"title":"二、Web SDK：一个克制的批量上报器","slug":"二、web-sdk-一个克制的批量上报器","link":"#二、web-sdk-一个克制的批量上报器","children":[{"level":3,"title":"2.1 UbaClient：单例 + 事件构造","slug":"_2-1-ubaclient-单例-事件构造","link":"#_2-1-ubaclient-单例-事件构造","children":[]},{"level":3,"title":"2.2 Batcher：双触发 + 并发守卫","slug":"_2-2-batcher-双触发-并发守卫","link":"#_2-2-batcher-双触发-并发守卫","children":[]},{"level":3,"title":"2.3 重试与降级：精确区分状态码","slug":"_2-3-重试与降级-精确区分状态码","link":"#_2-3-重试与降级-精确区分状态码","children":[]},{"level":3,"title":"2.4 页面卸载兜底：sendBeacon","slug":"_2-4-页面卸载兜底-sendbeacon","link":"#_2-4-页面卸载兜底-sendbeacon","children":[]},{"level":3,"title":"2.5 上下文：设备 / 会话 / 平台","slug":"_2-5-上下文-设备-会话-平台","link":"#_2-5-上下文-设备-会话-平台","children":[]},{"level":3,"title":"2.6 默认值一览","slug":"_2-6-默认值一览","link":"#_2-6-默认值一览","children":[]}]},{"level":2,"title":"三、C# SDK：零依赖核心 + 可注入传输","slug":"三、c-sdk-零依赖核心-可注入传输","link":"#三、c-sdk-零依赖核心-可注入传输","children":[{"level":3,"title":"3.1 IHttpTransport：为 Unity WebGL 留的口子","slug":"_3-1-ihttptransport-为-unity-webgl-留的口子","link":"#_3-1-ihttptransport-为-unity-webgl-留的口子","children":[]},{"level":3,"title":"3.2 UnityWebRequestTransport：把协程桥接到 Task","slug":"_3-2-unitywebrequesttransport-把协程桥接到-task","link":"#_3-2-unitywebrequesttransport-把协程桥接到-task","children":[]},{"level":3,"title":"3.3 Batcher：线程安全版","slug":"_3-3-batcher-线程安全版","link":"#_3-3-batcher-线程安全版","children":[]},{"level":3,"title":"3.4 零依赖：手写 JSON 序列化器","slug":"_3-4-零依赖-手写-json-序列化器","link":"#_3-4-零依赖-手写-json-序列化器","children":[]}]},{"level":2,"title":"四、Collector：把采集数据接住","slug":"四、collector-把采集数据接住","link":"#四、collector-把采集数据接住","children":[{"level":3,"title":"4.1 鉴权：加固实现","slug":"_4-1-鉴权-加固实现","link":"#_4-1-鉴权-加固实现","children":[]},{"level":3,"title":"4.2 字段回填的微妙之处","slug":"_4-2-字段回填的微妙之处","link":"#_4-2-字段回填的微妙之处","children":[]},{"level":3,"title":"4.3 两个 Topic","slug":"_4-3-两个-topic","link":"#_4-3-两个-topic","children":[]}]},{"level":2,"title":"五、跨端契约的一致性","slug":"五、跨端契约的一致性","link":"#五、跨端契约的一致性","children":[]},{"level":2,"title":"六、小结：采集层的工程美学","slug":"六、小结-采集层的工程美学","link":"#六、小结-采集层的工程美学","children":[]}],"git":{"updatedTime":1790747139000,"contributors":[{"name":"Bobo","username":"Bobo","email":"yanglinbo@gmail.com","commits":2,"url":"https://github.com/Bobo"}],"changelog":[{"hash":"364ea74d30204fdae1031ecf30a1626ff9d32852","time":1790747139000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."},{"hash":"a177b25888e97f93db07390b7db7566c539a314e","time":1782974568000,"email":"yanglinbo@gmail.com","author":"Bobo","message":"feat: add posts."}]},"filePathRelative":"posts/go-wind-uba-sdk-and-collector.md","excerpt":"\\n<blockquote>\\n<p>本文回答一个问题：<strong>一个埋点事件，从用户在浏览器里点了一下，到最终被 Kafka 接住，中间的 SDK 和 Collector 做了多少你看不见的工程？</strong> 答案是：比你想象的多得多。</p>\\n</blockquote>\\n<h2>一、为什么\\"采集\\"这件事很难</h2>\\n<p>很多人以为埋点 SDK 就是 <code>fetch('/report', { body: event })</code>。这在 demo 里成立，在生产里不成立。真实的采集层要回答这些问题：</p>\\n<ul>\\n<li><strong>页面随时可能关闭</strong>——用户点完就关 tab，残留事件怎么办？</li>\\n<li><strong>网络随时可能抖动</strong>——一次失败就丢数据？还是重试？重试几次？退避多久？</li>\\n<li><strong>服务端可能限流</strong>——429 要重试，但 401（鉴权失败）不该重试，怎么区分？</li>\\n<li><strong>批量还是单条</strong>——单条上报开销大，批量要攒多久、攒多少？</li>\\n<li><strong>客户端环境千差万别</strong>——浏览器的 sendBeacon、Unity WebGL 不能用 HttpClient、小程序没有 localStorage……</li>\\n<li><strong>凭证放哪</strong>——放 Header 还是 body？前者标准但不支持 sendBeacon。</li>\\n</ul>"}`);export{i as comp,r as data};
